import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

import React, { useState } from 'react';
import ConciergeDashboard from './screens/ConciergeDashboard';
import PackageEntry from './screens/PackageEntry';
import CommunityWall from './screens/CommunityWall';
import ResidentServices from './screens/ResidentServices';
import AdminDashboard from './screens/AdminDashboard';
import QRCodeScreen from './screens/QRCodeScreen';
import AccessControl from './screens/AccessControl';

// Navigation types
export type ScreenName = 
  | 'ConciergeDashboard' 
  | 'PackageEntry' 
  | 'CommunityWall' 
  | 'ResidentServices' 
  | 'AdminDashboard'
  | 'QRCodeScreen'
  | 'AccessControl';

const App: React.FC = () => {
  const [currentScreen, setCurrentScreen] = useState<ScreenName>('ConciergeDashboard');
  const [isMenuOpen, setIsMenuOpen] = useState(false);

  const renderScreen = () => {
    switch (currentScreen) {
      case 'ConciergeDashboard': return <ConciergeDashboard navigate={setCurrentScreen} />;
      case 'PackageEntry': return <PackageEntry navigate={setCurrentScreen} />;
      case 'CommunityWall': return <CommunityWall navigate={setCurrentScreen} />;
      case 'ResidentServices': return <ResidentServices navigate={setCurrentScreen} />;
      case 'AdminDashboard': return <AdminDashboard navigate={setCurrentScreen} />;
      case 'QRCodeScreen': return <QRCodeScreen navigate={setCurrentScreen} />;
      case 'AccessControl': return <AccessControl navigate={setCurrentScreen} />;
      default: return <ConciergeDashboard navigate={setCurrentScreen} />;
    }
  };

  return (
    <div className="min-h-screen bg-black flex justify-center items-center font-sans">

      {/* Mobile Frame Container */}
      <div className="relative w-full max-w-[420px] h-[100dvh] max-h-[900px] bg-ediflow-dark overflow-hidden shadow-2xl sm:rounded-[30px] sm:border-[8px] sm:border-[#333]">
        {/* Screen Content */}
        <div className="h-full w-full overflow-y-auto no-scrollbar bg-ediflow-dark text-ediflow-text relative">
          {renderScreen()}
        </div>

        {/* Floating Navigation Menu Trigger (For Demo Purposes) */}
        <div className="absolute bottom-6 right-6 z-50">
          <button 
            onClick={() => setIsMenuOpen(!isMenuOpen)}
            className="w-12 h-12 bg-white text-black rounded-full flex items-center justify-center shadow-lg hover:bg-gray-200 transition-all"
          >
            <span className="material-symbols-outlined">{isMenuOpen ? 'close' : 'menu'}</span>
          </button>
        </div>

        {/* Navigation Overlay */}
        {isMenuOpen && (
          <div className="absolute inset-0 bg-black/90 z-40 flex flex-col items-center justify-center space-y-4 backdrop-blur-sm p-6 animate-fade-in">
            <h2 className="text-ediflow-primary text-xl font-bold mb-4">Seleccionar Pantalla</h2>
            {[
              { id: 'ConciergeDashboard', label: 'Panel Conserje' },
              { id: 'PackageEntry', label: 'Ingresar Encomienda' },
              { id: 'AccessControl', label: 'Control Visitas' },
              { id: 'AdminDashboard', label: 'Panel Admin' },
              { id: 'ResidentServices', label: 'Servicios Residente' },
              { id: 'CommunityWall', label: 'Muro Comunidad' },
              { id: 'QRCodeScreen', label: 'Código QR' },
            ].map((screen) => (
              <button
                key={screen.id}
                onClick={() => {
                  setCurrentScreen(screen.id as ScreenName);
                  setIsMenuOpen(false);
                }}
                className={`w-full py-3 px-6 rounded-xl font-medium transition-all ${
                  currentScreen === screen.id 
                    ? 'bg-ediflow-primary text-black' 
                    : 'bg-ediflow-surface text-white hover:bg-ediflow-surfaceHighlight'
                }`}
              >
                {screen.label}
              </button>
            ))}
          </div>
        )}
      </div>
    </div>
  );
};

export default App;

import React, { useState } from 'react';
import { ScreenName } from '../App';

interface Props {
  navigate: (screen: ScreenName) => void;
}

const AdminDashboard: React.FC<Props> = ({ navigate }) => {
  return (
    <div className="flex flex-col min-h-full bg-[#101c22]">
      <div className="sticky top-0 z-20 bg-[#101c22]/95 backdrop-blur-sm px-5 py-4 flex items-center justify-between border-b border-white/5">
         <div>
            <h1 className="text-xl font-bold text-white">Panel de Control</h1>
            <div className="flex items-center gap-2 mt-1">
                <span className="w-2 h-2 rounded-full bg-green-500 shadow-[0_0_10px_rgba(34,197,94,0.5)]"></span>
                <span className="text-[10px] font-bold text-gray-400 uppercase tracking-widest">Vista Administrador</span>
            </div>
         </div>
         <button onClick={() => navigate('ConciergeDashboard')} className="w-10 h-10 rounded-full bg-[#1c262c] flex items-center justify-center text-white hover:bg-[#2a363e] transition-colors">
            <span className="material-symbols-outlined">settings_account_box</span>
         </button>
      </div>

      <div className="p-5 pb-24 space-y-6">
        {/* Metrics */}
        <div>
            <h2 className="text-xs font-bold text-gray-500 uppercase mb-3 ml-1">Métricas en Tiempo Real</h2>
            <div className="flex gap-3 overflow-x-auto no-scrollbar">
                <MetricCard icon="deck" color="text-[#13a4ec]" value="85%" label="Ocupación Quinchos" progress={85} progressColor="bg-[#13a4ec]" />
                <MetricCard icon="inventory_2" color="text-amber-500" value="12" label="Sin retirar (+48h)" progress={40} progressColor="bg-amber-500" warning />
                <MetricCard icon="assignment_late" color="text-purple-400" value="3" label="Reclamos Abiertos" progress={25} progressColor="bg-purple-400" />
            </div>
        </div>

        {/* Community Analytics Chart */}
        <div>
             <h2 className="text-xs font-bold text-gray-500 uppercase mb-3 ml-1">Estadísticas de la Comunidad</h2>
             <StatsChart />
        </div>

        {/* Administration */}
        <div>
             <h2 className="text-xs font-bold text-gray-500 uppercase mb-3 ml-1">Administración</h2>
             <div className="grid grid-cols-2 gap-3">
                <button className="bg-white text-[#101c22] p-4 rounded-xl shadow-lg active:scale-[0.98] transition-all flex flex-col items-start gap-3 h-32 relative overflow-hidden">
                    <div className="bg-[#101c22]/10 w-10 h-10 rounded-lg flex items-center justify-center">
                        <span className="material-symbols-outlined text-2xl">settings_b_roll</span>
                    </div>
                    <span className="text-sm font-bold leading-tight text-left">Configuración<br/>de Edificio</span>
                    <span className="material-symbols-outlined absolute -right-2 -bottom-2 text-[80px] text-black/5">apartment</span>
                </button>
                <button className="bg-[#13a4ec] text-white p-4 rounded-xl shadow-lg active:scale-[0.98] transition-all flex flex-col items-start gap-3 h-32 relative overflow-hidden">
                     <div className="bg-white/20 w-10 h-10 rounded-lg flex items-center justify-center backdrop-blur-sm">
                        <span className="material-symbols-outlined text-2xl">badge</span>
                    </div>
                    <span className="text-sm font-bold leading-tight text-left">Gestión de<br/>Personal</span>
                </button>
             </div>
        </div>

        {/* Modules Control */}
        <div>
             <div className="flex items-center justify-between mb-3 ml-1">
                 <h2 className="text-xs font-bold text-gray-500 uppercase">Control de Módulos</h2>
                 <button className="text-[#13a4ec] text-xs font-bold flex items-center gap-1">
                    <span className="material-symbols-outlined text-sm">tune</span> Personalizar
                 </button>
             </div>
             <div className="space-y-3">
                <ModuleItem icon="local_shipping" title="Encomiendas" desc="25 recibidas hoy" badge="8 pendientes" badgeColor="text-red-500 bg-red-500/10" color="text-blue-500 bg-blue-500/10" />
                <ModuleItem icon="deck" title="Espacios Comunes" desc="Quinchos y Sala" badge="4 Reservas" badgeColor="text-emerald-500 bg-emerald-500/10" color="text-emerald-500 bg-emerald-500/10" />
                <ModuleItem icon="menu_book" title="Libro Novedades" desc="Bitácora Digital" color="text-gray-400 bg-gray-500/10" />
             </div>
        </div>

      </div>

      <nav className="fixed bottom-0 w-full max-w-[420px] bg-[#151e24] border-t border-white/5 pb-6 pt-2 px-6 flex justify-between items-center z-30">
        <NavButton icon="dashboard" label="Resumen" active />
        <NavButton icon="admin_panel_settings" label="Gestión" />
        <NavButton icon="analytics" label="Finanzas" />
