const StatsChart = () => {
    const [activeTab, setActiveTab] = useState<'packages' | 'visitors' | 'requests'>('packages');

    const data = {
        packages: [12, 19, 15, 25, 22, 30, 18],
        visitors: [8, 12, 10, 15, 20, 25, 15],
